/** 后端 create/PATCH 的字段约束镜像：name strip 1–100 禁双引号换行；description ≤500；steps 走 validateWorkflowSteps。 */
function assertWorkflowFields(fields: { name?: string; description?: string; steps?: WorkflowStep[] }): void {
  if (fields.name !== undefined) {
    const name = fields.name.trim()
    if (!name || name.length > 100 || /["\r\n]/.test(name)) {
      throw new MockAdminRuleError('validation_error', '工作流名称需为 1–100 个字符，且不含双引号或换行')
