```ts
listWorkflowRuns(id: string, query: PageQuery): PageResult<WorkflowRun> | null {
  const workflow = this.workflows.find((item) => item.id === id)
  if (!workflow) return null
  if (workflow.scope === 'system') throw new MockAdminRuleError('forbidden', '系统模板运行历史仅模板所有者可查', 403)
  const rows = (this.workflowRuns[id] ?? []).map((row) => {
    const run = this.runs[row.run_id]
    return { ...row, run_status: run?.status ?? null, run_finished_at: run?.finished_at ?? null, run_duration_ms: run?.duration_ms ?? null, run_error_code: run?.error?.code ?? null }
  }).sort((a, b) => Date.parse(b.created_at) - Date.parse(a.created_at))
  return paginate(rows, query)
}
