  listWorkflows(query: PageQuery): PageResult<Workflow> {
    const filtered = [...this.workflows].sort((a, b) =>
      a.created_at === b.created_at ? b.id.localeCompare(a.id) : Date.parse(b.created_at) - Date.parse(a.created_at),
