      .sort((a, b) => Date.parse(b.updated_at) - Date.parse(a.updated_at))

    return {
      ...paginate(filtered, query),
      stats: {
        total: this.workflows.length,
        enabled: this.workflows.filter((item) => item.enabled).length,
